#include "so101_gazebo_demo/pick_place/plan_validation.hpp"
namespace so101_gazebo_demo::pick_place { void PlanValidatorRegistry::registerValidator(State s,std::shared_ptr<const IPlanValidator> v){validators_[s]=std::move(v);} bool PlanValidatorRegistry::hasValidator(State s)const noexcept{auto i=validators_.find(s);return i!=validators_.end()&&i->second;} ValidationResult PlanValidatorRegistry::validate(State s,const WorldSnapshot& w,const PlanArtifact&a)const{auto i=validators_.find(s);if(i==validators_.end()||!i->second)return {false,{{FailureCategory::CONFIGURATION,"PLAN_VALIDATOR_NOT_REGISTERED","validator missing",{}}},{}};return i->second->validate(s,w,a);} ValidationResult NonEmptyPlanValidator::validate(State,const WorldSnapshot&,const PlanArtifact&a)const{return a.trajectory_points?ValidationResult{true,{},{}}:ValidationResult{false,{{FailureCategory::PLAN_VALIDATION,"EMPTY_PLAN_ARTIFACT","empty plan",{}}},{}};} }
